import json
with open('map_data.json', 'r') as f:
    data = json.load(f)
plots = { (p['x'], p['y']): p for p in data['plots'] }
def get_neighbors(x, y):
    if y % 2 == 0:
        ns = [(x+1, y), (x-1, y), (x, y+1), (x, y-1), (x-1, y-1), (x-1, y+1)]
    else:
        ns = [(x+1, y), (x-1, y), (x, y+1), (x, y-1), (x+1, y-1), (x+1, y+1)]
    return [ (nx, ny) for nx, ny in ns if (nx, ny) in plots ]

target = (21, 14)
print(f'Target {target}: {plots[target]}')
for nxy in get_neighbors(*target):
    print(f'Neighbor {nxy}: {plots[nxy]}')
"

